import { audioSyncMarkup } from './audio-sync-markup.mjs';
import { singingMarkup } from './singing-practice.mjs';

export function bandMarkup() {
  return `<div class="band-heading" hidden><h2 id="b-title"></h2><p id="b-description"></p><span id="b-account"></span></div>
  <section id="b-room-panel" class="band-card" hidden aria-label="Teacher led sessions">
    <div class="band-row"><h3>Your jam sessions</h3><button id="b-refresh" class="button secondary">Refresh sessions</button></div>
    <p id="b-room-help">Sign in to create or join a teacher-led session.</p><div id="b-rooms" class="band-room-list"></div><details id="b-take-history" hidden><summary>Recent shared takes</summary><div id="b-takes"></div></details>
    <form id="b-create" hidden><h3>Start a new session</h3><div class="band-fields"><label>Song<select id="b-room-song"></select></label><label id="b-room-backing-picker" hidden>Backing<select id="b-room-backing"></select></label><label>First student<select id="b-student-a"></select></label><label>Part<select id="b-part-a"></select></label><label>Second student<select id="b-student-b"></select></label><label>Part<select id="b-part-b"></select></label></div><div id="b-extra-seats" class="band-fields"></div><div class="band-row"><button id="b-add-seat" type="button" class="text-button">+ Add student</button><button id="b-remove-seat" type="button" class="text-button" hidden>Remove last seat</button></div><p class="band-help">Choose up to eight different students; empty seats are ignored. Teacher-set passwords work immediately. Each student joins on their own computer. Guitar, bass and vocals follow along without scoring.</p><button class="button primary" type="submit">Create session</button></form>
    <div id="b-current-room" hidden><div class="band-row"><div><p class="eyebrow" id="b-room-state">PREPARING</p><h3 id="b-room-title"></h3></div><div class="band-row"><button id="b-leave" class="button secondary">Leave session</button><button id="b-room-close" class="button band-end-session" hidden>End session</button></div></div>
      <form id="b-session-config" hidden><h4>Song and playback</h4><div class="band-fields"><label>Session song<select id="b-session-song"></select></label><label id="b-session-backing-picker" hidden>Backing<select id="b-session-backing"></select></label><label>Start from bar<input id="b-session-from" type="number" min="1" value="1" required></label></div><div id="b-session-parts" class="band-fields"></div><button id="b-session-apply" type="submit" class="button secondary">Apply song / start bar</button><p class="band-help">Applying stops the current take and keeps everyone in this session. Check the parts, then everyone presses Ready for a new count-in.</p></form>
      <div class="band-row band-room-controls"><button id="b-ready" class="button primary">Check sound &amp; Ready</button><button id="b-room-start" class="button primary" hidden>Start together</button><button id="b-room-stop" class="button secondary" hidden>Stop playback</button></div><div id="b-performers" class="band-performers"></div>
      <p id="b-sync" class="band-help">Connecting…</p><label id="b-teacher-volume" hidden>Classroom backing volume <input id="b-speaker-volume" type="range" min="0" max="100" value="65"></label><p class="band-help">First classroom test: one backing speaker on the teacher computer. Students hear their instruments locally. Each computer grades its own input.</p></div>
  </section>
  <section class="band-card" id="b-practice" aria-label="Band part practice">
    <div class="band-fields" id="b-song-choices"><div id="b-practice-choices" class="practice-song-picker"><label id="b-song-picker" class="practice-song-picker"><span>Practice song</span><select id="b-song"></select></label><label id="b-backing-picker" class="backing-picker" hidden><span>Backing</span><select id="b-backing" aria-label="Backing track"></select></label></div><label id="b-part-picker">Your part<select id="b-part"></select></label></div>
    <div class="band-row"><p id="b-song-info" class="band-help"></p><button id="b-open-import" class="button secondary">Prepare band song ↑</button></div>
    <details id="b-input-controls" class="band-input" open><summary>Input and sound settings</summary><div class="band-row"><strong id="b-input-title">Your keyboard</strong><button id="b-connect" class="button secondary">Connect MIDI keyboard</button><button id="b-disconnect" class="text-button">Disconnect</button><button id="b-kit" class="button secondary" hidden>Connect / map drumkit</button></div><div class="band-fields"><label id="b-device-label">MIDI keyboard<select id="b-device"><option value="">No device selected</option></select></label><label id="b-channel-label">MIDI channel<select id="b-channel"><option value="all">All channels</option>` + Array.from({length:16},(_,i)=>'<option value="'+(i+1)+'">'+(i+1)+'</option>').join('') + `</select></label><label>Timing correction (ms)<input id="b-offset" type="number" min="-200" max="200" step="1" value="0"></label><label class="band-check"><input id="b-sound" type="checkbox" checked><span id="b-sound-label">App instrument sounds</span></label></div><p id="b-midi-state" class="band-help" role="status">Computer keys are ready. USB MIDI is optional.</p></details>
    <div class="band-row band-transport"><button id="b-play" class="button primary">▶ Play part</button><button id="b-listen" class="button secondary">Listen first</button><label class="band-check"><input id="b-click" type="checkbox" checked> Metronome</label><label>View<select id="b-view"><option value="highway">Note highway</option><option value="tab" hidden>Tablature · strings</option><option value="lyrics" hidden>Lyrics</option><option value="sheet" hidden>Sheet music · drums</option><option value="full" hidden>Full sheet · drums</option></select></label><label id="b-local-volume" hidden>Backing volume<input id="b-volume" type="range" min="0" max="100" value="65"></label><button id="b-fullscreen" class="score-icon-button" aria-label="Full screen instrument practice" title="Full screen">⛶</button></div>
    <details id="b-loop-controls" class="band-loop-controls"><summary>Practice a section</summary><div class="band-fields"><label class="band-check"><input id="b-loop-enabled" type="checkbox">Repeat selected bars</label><label>From bar<input id="b-loop-from" type="number" min="1" value="1"></label><label>Through bar<input id="b-loop-to" type="number" min="1" value="4"></label><label>Passes<select id="b-loop-repeats"><option value="1">1</option><option value="2">2</option><option value="4" selected>4</option><option value="8">8</option></select></label></div><p id="b-loop-state" class="band-help"></p></details><p id="b-follow-help" class="band-help" hidden></p><div id="b-stage" class="band-stage"><div id="b-full-controls" class="band-row" hidden><button id="b-full-play" class="button primary">▶ Play part</button><div id="b-full-song-slot"></div><span id="b-full-title"></span><small id="b-awake-state" role="status"></small><button id="b-full-exit" class="button secondary">Exit full screen</button></div><p id="b-play-status" role="status">Ready when you are.</p><canvas id="b-canvas" aria-label="Instrument note highway. Play when the note enters its hit box."></canvas><div id="b-full-scroll" class="full-score-scroll" hidden><div id="b-full-page"><canvas id="b-full-canvas"></canvas></div></div>${singingMarkup()}<div id="b-key-guide" class="band-key-guide" aria-label="Playable keys"></div></div>
    <p id="b-feedback" class="band-feedback" role="status">Listen to the pattern, then try it yourself.</p><div id="b-stats" class="band-stats"></div>
    <details id="b-key-controls"><summary>Change computer keys</summary><p class="band-help">Select a note, then press a key to assign it. Esc cancels. Enter is Play/Stop.</p><div class="band-row"><label>Computer-key octave<select id="b-octave"><option value="-24">C2–C3</option><option value="-12">C3–C4</option><option value="0" selected>C4–C5</option><option value="12">C5–C6</option><option value="24">C6–C7</option></select></label><button id="b-reset-keys" class="text-button">Reset keyboard keys</button></div><div id="b-bindings" class="band-bindings"></div></details>
    <section id="b-report" class="band-report" hidden><div class="band-row"><h3>Your last take</h3><button id="b-open-report" class="button secondary">Open detailed report</button><button id="b-csv" class="button secondary">Download note timing CSV</button></div><p id="b-report-summary"></p><div class="band-report-notes" id="b-report-notes"></div><p id="b-save-state" role="status"></p><button id="b-retry-save" class="text-button" hidden>Retry saving result</button></section>
  </section>
  <section id="b-editor-workspace" hidden aria-label="MIDI and audio sync">
    <header class="sync-workspace-heading"><h2>MIDI &amp; audio sync</h2><p>Choose a song, compare its MIDI parts with the waveform, and save the backing settings for your class.</p></header>
    <div class="band-fields sync-song-choices"><label>School song<select id="b-editor-song"><option value="">Choose a school song…</option></select></label><button id="b-editor-new" class="button secondary">New arrangement</button></div>
    <p class="band-help" id="b-editor-help">Choose a school song above, or import MIDI for a new arrangement. Changes stay in the draft until you publish.</p>
  <section id="b-import-panel" class="band-card band-import-panel" hidden aria-label="Prepare a MIDI arrangement">
    <div class="band-row"><h3 id="b-import-heading">Prepare your band song</h3><button id="b-import-close" class="button secondary">Done</button></div>
    <div class="band-fields"><label>Title<input id="b-import-title" maxlength="120"></label><label>MIDI file<input id="b-midi-file" type="file" accept=".mid,.midi"></label></div>
    <div class="band-editor-tabs" role="tablist" aria-label="Song editor"><button id="b-import-audio-button" type="button" role="tab" aria-controls="b-import-audio-tab" aria-selected="false">Audio &amp; backing</button><button id="b-import-parts-button" type="button" role="tab" aria-controls="b-import-parts-tab" aria-selected="true">Parts &amp; lyrics</button></div>
    <section id="b-import-audio-tab" role="tabpanel" aria-labelledby="b-import-audio-button" hidden>
      <h4>Choose your backing track</h4><p class="band-help">Load a different recording, match it to the MIDI, then preview the start and a later section before publishing.</p>
      <div class="backing-manager"><div class="band-fields"><label>Backing version<select id="b-edit-backing" aria-label="Backing version to calibrate"></select></label><label>Student-facing name<input id="b-backing-label" maxlength="80" placeholder="e.g. Songsterr · MIDI aligned"></label><label class="band-check"><input id="b-backing-default" type="checkbox"> Default for students</label><button id="b-add-backing" class="button secondary">+ Add another backing</button></div><p class="band-help">Each version keeps its own alignment, volume and start/end cuts. Adding a version keeps the other recordings. Publish to make all versions available to students.</p></div><div class="band-fields"><label>Replace selected backing file<input id="b-audio-file" type="file" accept="audio/*"></label><button id="b-clear-audio" class="text-button">Remove selected version</button></div><p id="b-backing-current" class="band-help" role="status"></p><p id="b-backing-length-state" class="band-help band-backing-check"></p>
      <div class="band-fields"><label>Background volume <span id="b-backing-volume-value">65%</span><input id="b-import-volume" aria-label="Background volume" type="range" min="0" max="100" value="65"></label><label>Recording offset (seconds)<input id="b-import-offset" type="number" min="-300" max="300" step="0.001" value="0"></label><label>MIDI speed (%)<input id="b-import-speed" type="number" min="50" max="200" step="0.001" value="100"></label></div>
      <p class="band-help">Positive offset delays the recording; negative offset skips its intro. MIDI speed follows the recording without changing the audio's pitch.</p><p id="b-backing-lyrics-state" class="band-help"></p>
      <fieldset class="backing-range"><legend>Keep this part of the recording</legend><div class="band-fields"><label>Start at (recording seconds)<input id="b-audio-start" type="number" min="0" step="0.001" value="0"></label><label>End at (recording seconds)<input id="b-audio-end" type="number" min="0" step="0.001" placeholder="End of recording"></label></div><div class="sync-buttons"><button id="b-trim-start" type="button" class="button secondary">Start at waveform cursor</button><button id="b-trim-end" type="button" class="button secondary">End at waveform cursor</button><button id="b-trim-align" type="button" class="button secondary">Align start to selected MIDI beat</button><button id="b-trim-reset" type="button" class="text-button">Use whole recording</button></div><p id="b-range-state" class="band-help" role="status">Cuts are reversible. The original file and MIDI alignment are preserved.</p></fieldset>
      <label class="band-sync-reference">Compare against<select id="b-sync-reference"></select></label>${audioSyncMarkup('b-')}
    </section>
    <section id="b-import-parts-tab" role="tabpanel" aria-labelledby="b-import-parts-button"><p class="band-help">Assign the MIDI tracks for each instrument. Ignored tracks remain in the backing recording.</p><div id="b-import-tracks"></div><details id="b-lyrics-editor"><summary>Vocals and timed lyrics</summary><p id="b-lyric-detected" class="band-help"></p><label>Load lyrics (.txt, .lrc, .vtt, .srt)<input id="b-lyrics-file" type="file" accept=".lrc,.vtt,.srt,.txt"></label><details id="b-lyric-timing"><summary>Time plain lyrics with the recording</summary><p class="band-help">Paste one line per cue. Play or seek the backing and mark each line as it begins. End a line before an instrumental gap. These timings use this exact recording.</p><label>Plain lyrics, one line per cue<textarea id="b-lyric-plain" rows="8"></textarea></label><button id="b-lyric-timing-start" type="button" class="button secondary">Start line timing</button><div id="b-lyric-player" hidden><audio id="b-lyric-audio" controls preload="metadata"></audio><p id="b-lyric-next-line" role="status"></p><div class="band-row"><button id="b-lyric-mark" type="button" class="button primary">Mark next line</button><button id="b-lyric-end" type="button" class="button secondary">End current line</button><button id="b-lyric-undo" type="button" class="text-button">Undo last line</button><button id="b-lyric-timing-apply" type="button" class="button secondary">Use timed vocal part</button></div></div></details><label>Timed lyrics<textarea id="b-lyrics-text" rows="8" placeholder="[00:00.000]Your first line&#10;[00:08.000]Your next line"></textarea></label><div class="band-fields"><label>Lyric timestamps follow<select id="b-lyrics-clock"><option value="midi">MIDI song time</option><option value="recording">Backing recording time</option></select></label><label>Lyric adjustment (seconds)<input id="b-lyrics-offset" type="number" min="-300" max="300" step="0.001" value="0"></label></div><p class="band-help">Embedded MIDI lyrics load when available. Otherwise add your own timed lyric file or timestamp each line. Recording time follows the saved backing offset; MIDI time follows MIDI speed. Positive adjustment displays lyrics later. No microphone or vocal score is required.</p></details></section>
    <p class="band-help">Use the arrangement locally to try your draft. Publish the school song update to share the backing and alignment with students.</p>
    <div class="band-row"><button id="b-import-apply" class="button primary">Use arrangement locally</button><button id="b-publish" class="button secondary">Publish new school song</button><button id="b-setup-save" class="button secondary">Download arrangement setup</button><label class="button secondary file-pick">Load arrangement setup<input id="b-setup-file" type="file" accept=".json"></label></div><p id="b-import-state" role="status"></p>
  </section>
  </section><p id="b-message" class="band-message" role="status"></p>`;
}
